import{_ as p,a0 as o,w as d,s as r,I as a,x as s,a1 as t,A as l,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"在 FreeDOS 中設置你的路徑 | LCTT x X-CMD","titleTemplate":false,"description":"在 FreeDOS 中設置你的路徑 | LCTT (202103) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 FreeDOS 中設置你的路徑 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 FreeDOS 中設置你的路徑 | LCTT (202103) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202103/20210224 Set your path in FreeDOS","title":"在 FreeDOS 中設置你的路徑","tag":"202103","desc":""},"relativePath":"202103/20210224 Set your path in FreeDOS.md","filePath":"[post].md"}'),h={name:"202103/20210224 Set your path in FreeDOS.md"};function g(u,e,k,b,c,f){const i=o("Link");return d(),r("div",null,[e[26]||(e[26]=a("h1",{id:"在-freedos-中設置你的路徑",tabindex:"-1"},[s("在 FreeDOS 中設置你的路徑 "),a("a",{class:"header-anchor",href:"#在-freedos-中設置你的路徑","aria-label":"Permalink to “在 FreeDOS 中設置你的路徑”"},"​")],-1)),e[27]||(e[27]=a("blockquote",null,[a("p",null,"學習 FreeDOS 路徑的知識，如何設置它，並且如何使用它。")],-1)),e[28]||(e[28]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/career_journey_road_gps_path_map_520.png?itok=PpL6jJgY",alt:"查看職業生涯地圖",title:"Looking at a map for career journey"})],-1)),a("p",null,[e[1]||(e[1]=s("你在開源 ",-1)),t(i,{href:"https://www.freedos.org/"},{default:l(()=>[...e[0]||(e[0]=[s("FreeDOS",-1)])]),_:1}),e[2]||(e[2]=s(" 操作系統中所做的一切工作都是通過命令列完成的。命令列以一個 ",-1)),e[3]||(e[3]=a("em",null,"提示符",-1)),e[4]||(e[4]=s(" 開始，這是計算機説法的方式，“我準備好了。請給我一些事情來做。”你可以配置你的提示符的外觀，但是默認情況下，它是：",-1))]),e[29]||(e[29]=n('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;</span></span></code></pre></div><p>從命令列中，你可以做兩件事：運行一個內部命令或運行一個程序。外部命令是在你的 <code>FDOS</code> 目錄中可找到的以單獨文件形式存在的程序，以便運行程序包括運行外部命令。它也意味着你可以使用你的計算機運行應用程序軟件來做一些東西。你也可以運行一個批處理文件，但是在這種情況下，你所做的全部工作就變成了運行批處理文件中所列出的一系列命令或程序。</p><h3 id="可執行應用程序文件" tabindex="-1">可執行應用程序文件 <a class="header-anchor" href="#可執行應用程序文件" aria-label="Permalink to “可執行應用程序文件”">​</a></h3><p>FreeDOS 可以運行三種類型的應用程序文件：</p><ol><li><strong>COM</strong> 是一個用機器語言寫的，且小於 64 KB 的文件。</li><li><strong>EXE</strong> 也是一個用機器語言寫的文件，但是它可以大於 64 KB 。此外，在 EXE 文件的開頭部分有信息，用於告訴 DOS 系統該文件是什麼類型的以及如何加載和運行。</li><li><strong>BAT</strong> 是一個使用文本編輯器以 ASCII 文本格式編寫的 <em>批處理文件</em> ，其中包含以批處理模式執行的 FreeDOS 命令。這意味着每個命令都會按順序執行到文件的結尾。</li></ol><p>如果你所輸入的一個文件名稱不能被 FreeDOS 識別為一個內部命令或一個程序，你將收到一個錯誤消息 “Bad command or filename” 。如果你看到這個錯誤，它意味着會是下面三種情況中的其中一種：</p><ol><li>由於某些原因，你所給予的名稱是錯誤的。你可能拼錯了文件名稱，或者你可能正在使用錯誤的命令名稱。檢查名稱和拼寫，並再次嘗試。</li><li>可能你正在嘗試運行的程序並沒有安裝在計算機上。請確認它已經安裝了。</li><li>文件確實存在，但是 FreeDOS 不知道在哪裏可以找到它。</li></ol>',7)),a("p",null,[e[6]||(e[6]=s("在清單上的最後一項就是這篇文章的主題，它被稱為路徑。如果你已經習慣於使用 Linux 或 Unix ，你可能已經理解 ",-1)),t(i,{href:"https://opensource.com/article/17/6/set-path-linux"},{default:l(()=>[...e[5]||(e[5]=[s("PATH 變量",-1)])]),_:1}),e[7]||(e[7]=s(" 的概念。如果你是命令列的新手，那麼路徑是一個非常重要的足以讓你舒適的東西。",-1))]),e[30]||(e[30]=n(`<h3 id="路徑" tabindex="-1">路徑 <a class="header-anchor" href="#路徑" aria-label="Permalink to “路徑”">​</a></h3><p>當你輸入一個可執行應用程序文件的名稱時，FreeDOS 必須能找到它。FreeDOS 會在一個具體指定的位置層次結構中查找文件：</p><ol><li>首先，它查找當前驅動器的活動目錄（稱為 <em>工作目錄</em>）。如果你正在目錄 <code>C:\\FDOS</code> 中，接着，你輸入名稱 <code>FOOBAR.EXE</code>，FreeDOS 將在 <code>C:\\FDOS</code> 中查找帶有這個名稱的文件。你甚至不需要輸入完整的名稱。如果你輸入 <code>FOOBAR</code> ，FreeDOS 將查找任何帶有這個名稱的可執行文件，不管它是 <code>FOOBAR.EXE</code>，<code>FOOBAR.COM</code>，或 <code>FOOBAR.BAT</code>。只要 FreeDOS 能找到一個匹配該名稱的文件，它就會運行該可執行文件。</li><li>如果 FreeDOS 不能找到你所輸入名稱的文件，它將查詢被稱為 <code>PATH</code> 的一些東西。每當 DOS 不能在當前活動命令中找到文件時，會指示 DOS 檢查這個列表中目錄。</li></ol><p>你可以隨時使用 <code>path</code> 命令來查看你的計算機的路徑。只需要在 FreeDOS 提示符中輸入 <code>path</code> ，FreeDOS 就會返回你的路徑設置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;path</span></span>
<span class="line"><span>PATH=C:\\FDOS\\BIN</span></span></code></pre></div><p>第一行是提示符和命令，第二行是計算機返回的東西。你可以看到 DOS 第一個查看的位置就是位於 <code>C</code> 驅動器上的 <code>FDOS\\BIN</code>。如果你想更改你的路徑，你可以輸入一個 <code>path</code> 命令以及你想使用的新路徑：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;path=C:\\HOME\\BIN;C:\\FDOS\\BIN</span></span></code></pre></div><p>在這個示例中，我設置我的路徑到我個人的 <code>BIN</code> 文件夾，我把它放在一個叫 <code>HOME</code> 的自定義目錄中，然後再設置為 <code>FDOS/BIN</code>。現在，當你檢查你的路徑時：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;path</span></span>
<span class="line"><span>PATH=C:\\HOME\\BIN;C:\\FDOS\\BIN</span></span></code></pre></div><p>路徑設置是按所列目錄的順序處理的。</p><p>你可能會注意到有一些字符是小寫的，有一些字符是大寫的。你使用哪一種都真的不重要。FreeDOS 是不區分大小寫的，並且把所有的東西都作為大寫字母對待。在內部，FreeDOS 使用的全是大寫字母，這就是為什麼你看到來自你命令的輸出都是大寫字母的原因。如果你以小寫字母的形式輸入命令和文件名稱，在一個轉換器將自動轉換它們為大寫字母后，它們將被執行。</p><p>輸入一個新的路徑來替換先前設置的路徑。</p><h3 id="autoexec-bat-文件" tabindex="-1">autoexec.bat 文件 <a class="header-anchor" href="#autoexec-bat-文件" aria-label="Permalink to “autoexec.bat 文件”">​</a></h3><p>你可能遇到的下一個問題的是 FreeDOS 默認使用的第一個路徑來自何處。這與其它一些重要的設置一起定義在你的 <code>C</code> 驅動器的根目錄下的 <code>AUTOEXEC.BAT</code> 文件中。這是一個批處理文件，它在你啓動 FreeDOS 時會自動執行（由此得名）。你可以使用 FreeDOS 程序 <code>EDIT</code> 來編輯這個文件。為查看或編輯這個文件的內容，輸入下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;edit autoexec.bat</span></span></code></pre></div><p>這一行出現在頂部附近：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SET PATH=%dosdir%\\BIN</span></span></code></pre></div><p>這一行定義默認路徑的值。</p><p>在你查看 <code>AUTOEXEC.BAT</code> 後，你可以通過依次按下面的按鍵來退出 EDIT 應用程序：</p><ol><li><code>Alt</code></li><li><code>f</code></li><li><code>x</code></li></ol><p>你也可以使用鍵盤快捷鍵 <code>Alt+X</code>。</p><h3 id="使用完整的路徑" tabindex="-1">使用完整的路徑 <a class="header-anchor" href="#使用完整的路徑" aria-label="Permalink to “使用完整的路徑”">​</a></h3><p>如果你在你的路徑中忘記包含 <code>C:\\FDOS\\BIN</code> ，那麼你將不能快速訪問存儲在這裏的任何應用程序，因為 FreeDOS 不知道從哪裏找到它們。例如，假設我設置我的路徑到我個人應用程序集合：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;path=C:\\HOME\\BIN</span></span></code></pre></div><p>內置在命令列中應用程序仍然能正常工作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\cd HOME</span></span>
<span class="line"><span>C:\\HOME&gt;dir</span></span>
<span class="line"><span>ARTICLES</span></span>
<span class="line"><span>BIN</span></span>
<span class="line"><span>CHEATSHEETS</span></span>
<span class="line"><span>GAMES</span></span>
<span class="line"><span>DND</span></span></code></pre></div><p>不過，外部的命令將不能運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:HOME\\ARTICLES&gt;BZIP2 -c example.txt</span></span>
<span class="line"><span>Bad command or filename - &quot;BZIP2&quot;</span></span></code></pre></div><p>通過提供命令的一個 <em>完整路徑</em> ，你可以總是執行一個在你的系統上且不在你的路徑中的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:HOME\\ARTICLES&gt;C:\\FDOS\\BIN\\BZIP2 -c example.txt</span></span>
<span class="line"><span>C:HOME\\ARTICLES&gt;DIR</span></span>
<span class="line"><span>example.txb</span></span></code></pre></div><p>你可以使用同樣的方法從外部介質或其它目錄執行應用程序。</p><h3 id="freedos-路徑" tabindex="-1">FreeDOS 路徑 <a class="header-anchor" href="#freedos-路徑" aria-label="Permalink to “FreeDOS 路徑”">​</a></h3><p>通常情況下，你很可能希望在路徑中保留 <code>C:\\PDOS\\BIN</code> ，因為它包含所有使用 FreeDOS 分發的默認應用程序。</p><p>除非你更改 <code>AUTOEXEC.BAT</code> 中的路徑，否則將在重新啓動後恢復默認路徑。</p><p>現在，你知道如何在 FreeDOS 中管理你的路徑，你能夠以最適合你的方式了執行命令和維護你的工作環境。</p>`,35)),a("p",null,[a("em",null,[e[9]||(e[9]=s("致謝 ",-1)),t(i,{href:"https://www.ahuka.com/dos-lessons-for-self-study-purposes/dos-lesson-5-the-path/"},{default:l(()=>[...e[8]||(e[8]=[s("DOS 課程 5: 路徑",-1)])]),_:1}),e[10]||(e[10]=s(" (在 CC BY-SA 4.0 協議下發布) 為本文提供的一些信息。",-1))])]),e[31]||(e[31]=a("hr",null,null,-1)),a("p",null,[e[12]||(e[12]=s("via: ",-1)),t(i,{href:"https://opensource.com/article/21/2/path-freedos"},{default:l(()=>[...e[11]||(e[11]=[s("https://opensource.com/article/21/2/path-freedos",-1)])]),_:1})]),a("p",null,[e[17]||(e[17]=s("作者：",-1)),t(i,{href:"https://opensource.com/users/ahuka"},{default:l(()=>[...e[13]||(e[13]=[s("Kevin O'Brien",-1)])]),_:1}),e[18]||(e[18]=s(" 選題：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[14]||(e[14]=[s("lujun9972",-1)])]),_:1}),e[19]||(e[19]=s(" 譯者：",-1)),t(i,{href:"https://github.com/robsean"},{default:l(()=>[...e[15]||(e[15]=[s("robsean",-1)])]),_:1}),e[20]||(e[20]=s(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:l(()=>[...e[16]||(e[16]=[s("wxy",-1)])]),_:1})]),a("p",null,[e[23]||(e[23]=s("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[21]||(e[21]=[s("LCTT",-1)])]),_:1}),e[24]||(e[24]=s(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:l(()=>[...e[22]||(e[22]=[s("Linux中國",-1)])]),_:1}),e[25]||(e[25]=s(" 榮譽推出",-1))])])}const m=p(h,[["render",g]]);export{S as __pageData,m as default};
